const RELAY_ASSETS={"/": "<!doctype html><html lang=\"zh-CN\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Relay · Workers 订阅网关</title><link rel=\"stylesheet\" href=\"/assets/style.css\"></head><body class=\"auth-mode\"><aside><a class=\"brand\" href=\"#vps\"><span>R</span>relay<span class=\"brand-dot\">.</span></a><p class=\"nav-label\">订阅网关</p><nav><a href=\"#vps\">▦　VPS 管理</a><a href=\"#registration\">⚿　注册设置</a><a href=\"#security\">账户安全</a></nav><div class=\"aside-bottom\"><span class=\"edge-icon\">☁</span><b>Cloudflare Workers</b><small>仅转发订阅请求</small></div></aside><main><header><span>Relay　/　<span id=\"breadcrumb\">VPS 管理</span></span><div><button class=\"btn\" id=\"logout\">退出登录</button><span class=\"avatar\">AD</span></div></header><div class=\"content\"><div class=\"notice\">订阅反向代理网关 · 各 VPS 独立注册与回源，不合并用户数据。</div><div id=\"page\"></div><footer>Relay Gateway<span>各 VPS 独立管理用户与节点</span></footer></div></main><dialog id=\"modal\"></dialog><div id=\"toast\" role=\"status\"></div><script src=\"/assets/app.js\"></script></body></html>\n", "/assets/style.css": ":root{font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",\"PingFang SC\",sans-serif;color:#22332e;background:#f5f7f9;font-size:16px;--green:#167f69;--muted:#78877f;--line:#e3e9e6}*{box-sizing:border-box}body{margin:0}button,input{font:inherit}button,a,input{outline-offset:4px}button{cursor:pointer}a{color:inherit;text-decoration:none}aside{position:fixed;inset:0 auto 0 0;width:230px;background:#fff;border-right:1px solid var(--line);padding:28px 20px;display:flex;flex-direction:column}.brand{font-size:32px;letter-spacing:-1.5px;font-weight:750;display:flex;align-items:center;gap:10px}.brand>span:first-child{background:#438a77;color:white;border-radius:10px;font-size:23px;padding:5px 10px}.brand-dot{color:#438a77;margin-left:-7px}.nav-label{font-size:13px;color:var(--muted);margin:44px 12px 12px}nav{display:grid;gap:8px}nav a{font-size:15px;padding:15px 14px;border-radius:8px;color:#6a7b72}nav a.active{background:#eaf4ef;color:#24745c;font-weight:600}.aside-bottom{margin-top:auto;border-top:1px solid var(--line);padding:24px 8px 8px;display:grid;gap:6px;font-size:14px}.aside-bottom small{color:var(--muted);font-size:13px}.edge-icon{color:var(--green);font-size:25px}main{margin-left:230px}header{height:78px;padding:0 36px;background:#fff;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center;font-size:14px;color:#738078}header>div{display:flex;align-items:center;gap:18px}.preview-badge{padding:6px 10px;border:1px solid var(--line);border-radius:5px}.avatar{background:#eef1ec;border-radius:50%;padding:10px;color:#6c786b;font-size:12px}.content{padding:30px 36px;max-width:1640px;margin:auto}.notice{background:#edf6f2;border:1px solid #dcece5;border-radius:8px;padding:14px 18px;color:#587a6a;font-size:14px;line-height:1.6}.title-row{display:flex;justify-content:space-between;align-items:center;gap:20px;margin:28px 0 24px}h1{font-size:29px;letter-spacing:-.7px;margin:0 0 10px}h2{font-size:18px;margin:0 0 12px}h3{font-size:16px}.subtitle,p.muted{font-size:14px;color:var(--muted);line-height:1.7;margin:0}.btn{padding:11px 16px;border-radius:7px;border:1px solid #d7e1db;background:#fff;color:#4f6258;font-size:14px;white-space:nowrap}.btn:hover{background:#f0f5f2}.btn.primary{background:var(--green);border-color:var(--green);color:white}.btn.danger{background:#ac4949;border-color:#ac4949;color:white}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-bottom:24px}.card{border:1px solid var(--line);background:white;border-radius:10px}.stat{padding:22px}.stat-label{font-size:14px;color:#738278}.stat strong{display:block;font-size:30px;margin:12px 0 8px}.stat small{font-size:13px;color:var(--muted)}.stat strong em{font-size:15px;font-style:normal;margin-left:7px;font-weight:400;color:var(--muted)}.table-toolbar{padding:20px;display:flex;justify-content:space-between;align-items:center;gap:16px}.search{width:330px;max-width:100%;padding:11px 13px;border:1px solid #dae4dd;border-radius:7px;background:#fbfcfb}.filters{display:flex;gap:6px;background:#f1f5f2;border-radius:7px;padding:4px}.filters button{padding:7px 13px;border:0;border-radius:5px;background:transparent;color:#7a897e;font-size:14px}.filters button.active{background:white;color:var(--green);box-shadow:0 1px 4px #173b2010}.table-wrap{overflow-x:auto}table{border-collapse:collapse;min-width:900px;width:100%;text-align:left}th{font-weight:500;background:#fafcfb;color:#829087;font-size:13px;padding:14px 20px;border-block:1px solid #edf1ee}td{padding:23px 20px;border-bottom:1px solid #edf1ee;font-size:14px;vertical-align:middle}tr:last-child td{border-bottom:0}.name{display:flex;align-items:center;gap:12px}.node-icon{display:grid;place-items:center;width:36px;height:36px;background:#eaf1ee;color:#52806a;border-radius:8px;font-size:13px}.name b{font-weight:600;display:block}.name small{display:block;font-size:12px;color:#8c9990;margin-top:6px}.ip{font-family:ui-monospace,SFMono-Regular,monospace;font-size:16px;font-weight:600;color:#2d5947}.uuid{display:block;color:#8c9990;font-size:12px;margin-top:7px;font-family:ui-monospace,monospace}.origin{font-size:13px;color:#748579;max-width:230px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.badge{display:inline-flex;align-items:center;gap:6px;font-size:13px;padding:5px 9px;border-radius:5px;color:#368161;background:#edf7f0}.badge.off{background:#f1f2f3;color:#8b9291}.badge.warning{background:#fff5e4;color:#a88339}.badge:before{content:'';width:5px;height:5px;border-radius:50%;background:currentColor}.op{border:0;background:none;padding:5px 7px;color:#45856b;font-size:14px}.op.red{color:#ab6a6a}.table-footer{padding:16px 20px;color:#8b998f;font-size:13px;border-top:1px solid var(--line)}.explain{margin-top:20px;color:#829187;line-height:1.8;font-size:13px}.explain b{color:#587463;font-weight:500}.settings-grid{display:grid;grid-template-columns:1.3fr 1fr;gap:22px}.settings-card{padding:26px}.setting-row{display:flex;align-items:center;justify-content:space-between;gap:24px;padding:20px 0;border-bottom:1px solid var(--line)}.setting-row h3{margin:0 0 6px}.switch{border:0;border-radius:20px;width:44px;height:25px;flex-shrink:0;background:#bec9c2;padding:3px}.switch:after{content:'';display:block;height:19px;width:19px;border-radius:50%;background:#fff;transition:transform .15s}.switch.on{background:var(--green)}.switch.on:after{transform:translateX(19px)}label{display:block;color:#637a6a;font-size:14px;margin:22px 0 8px}input:not([type=checkbox]){display:block;width:100%;padding:12px 13px;border:1px solid #d8e2db;border-radius:7px;margin-top:9px;background:#fff;color:#243e2e}.actions{display:flex;justify-content:flex-end;gap:10px;margin-top:24px}.token-state{display:flex;align-items:center;justify-content:space-between;border:1px solid var(--line);background:#f7faf8;padding:16px;margin-top:22px;border-radius:8px}.token-state code{font-size:17px;color:#819c8b;letter-spacing:2px}.token-state small{color:var(--muted);font-size:12px}.settings-card ul{padding-left:20px;color:#708477;font-size:14px;line-height:2}.code{background:#f3f6f4;padding:14px;font:13px/1.8 ui-monospace,monospace;overflow-wrap:anywhere;border-radius:6px}.field-pair{display:grid;grid-template-columns:1fr 1fr;gap:18px}dialog{border:1px solid var(--line);border-radius:12px;padding:28px;width:540px;max-width:calc(100vw - 28px);color:inherit;box-shadow:0 24px 100px #18332930}dialog::backdrop{background:#1a2e3044;backdrop-filter:blur(4px)}dialog p{font-size:14px;line-height:1.8;color:#748579}dialog input{min-width:0}dialog .code{user-select:all}footer{display:flex;justify-content:space-between;color:#9aa69e;font-size:12px;margin-top:32px}#toast{position:fixed;bottom:28px;left:50%;transform:translateX(-50%);background:#244a39;color:#fff;border-radius:8px;padding:13px 20px;font-size:14px;display:none;z-index:99}#toast.show{display:block}.empty{text-align:center;padding:50px;color:#8a9b90}@media(max-width:1000px){aside{width:190px}main{margin-left:190px}.content{padding:24px}.settings-grid{grid-template-columns:1fr}.title-row{align-items:flex-start}}@media(max-width:650px){aside{position:static;width:100%;padding:16px;display:block;border-bottom:1px solid var(--line)}.brand{font-size:26px}.nav-label,.aside-bottom{display:none}nav{display:flex;margin-top:16px}nav a{font-size:14px;padding:10px}main{margin:0}header{height:60px;padding:0 18px}.content{padding:18px}.summary{gap:10px}.stat{padding:15px 12px}.stat strong{font-size:25px}.stat small{font-size:12px}.table-toolbar{flex-direction:column;align-items:stretch}.search{width:100%}.filters{align-self:flex-start}.title-row{flex-wrap:wrap}.field-pair{grid-template-columns:1fr}.settings-card{padding:20px}footer span{display:none}}\n.filters{flex-shrink:0}.filters button,.badge,.name b{white-space:nowrap}.table-toolbar .search{min-width:120px;flex:1}.name small{white-space:nowrap}@media(max-width:1100px){table{min-width:640px}th:nth-child(3),td:nth-child(3),th:nth-child(5),td:nth-child(5){display:none}th,td{padding-left:14px;padding-right:14px}}\n\n.auth-mode aside,.auth-mode header,.auth-mode .notice,.auth-mode footer{display:none}.auth-mode main{margin:0}.auth-mode .content{min-height:100vh;display:grid;place-items:center}.auth-card{padding:36px;width:440px;max-width:100%}.auth-card h1{font-size:24px;margin-top:28px}.auth-card form>.btn{width:100%;margin-top:16px}.form-error{color:#ad4949;font-size:14px;line-height:1.7}\n", "/assets/app.js": "const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nlet state=null,csrf='',filter='all',query='',toastTimer;\nconst date=ts=>ts?new Date(ts*1000).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}):'尚无记录';\nfunction toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}\nasync function api(path,body){const r=await fetch(path,{method:body?'POST':'GET',credentials:'same-origin',headers:body?{'Content-Type':'application/json','X-CSRF-Token':csrf}:{},body:body?JSON.stringify(body):undefined});const data=await r.json();if(!r.ok){if(r.status===401&&!path.endsWith('/login'))showLogin();throw Error(data.error||'请求失败')}return data}\nfunction modal(html){const d=$('#modal');d.innerHTML=html;let down=false;const outside=e=>{const r=d.getBoundingClientRect();return e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom};d.onpointerdown=e=>down=e.target===d&&outside(e);d.onclick=e=>{if(down&&e.target===d&&outside(e))d.close();down=false};if(!d.open)d.showModal()}\nfunction accept(data){state=data;csrf=data.csrf;render()}\nasync function refresh(){accept(await api('/api/state'))}\nfunction showLogin(setup=false){csrf='';state=null;document.body.classList.add('auth-mode');$('#modal').close();$('#page').innerHTML=`<section class=\"card auth-card\"><div class=\"brand\"><span>R</span>relay.</div><h1>${setup?'首次设置管理员密码':'登录订阅网关'}</h1><p class=\"subtitle\">${setup?'账号固定为 dywsun，设置完成后初始化入口关闭。':'管理 VPS 绑定与订阅代理权限。'}</p><form id=\"authForm\"><label>管理员账户<input name=\"username\" value=\"dywsun\" readonly autocomplete=\"username\"></label><label>${setup?'设置密码':'密码'}<input name=\"password\" type=\"password\" ${setup?'minlength=\"12\"':''} maxlength=\"256\" autocomplete=\"${setup?'new-password':'current-password'}\" required></label>${setup?'<label>再次输入密码<input name=\"confirm\" type=\"password\" minlength=\"12\" maxlength=\"256\" autocomplete=\"new-password\" required></label>':''}<p id=\"authError\" class=\"form-error\" role=\"alert\"></p><button class=\"btn primary\" type=\"submit\">${setup?'设置密码':'登录'}</button></form></section>`;$('#authForm').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('[type=submit]');button.disabled=true;try{const p=Object.fromEntries(new FormData(e.target));if(setup){await api('/api/setup',p);showLogin();toast('密码已设置，请登录')}else{csrf=(await api('/api/login',p)).csrf;await refresh()}}catch(error){if($('#authError'))$('#authError').textContent=error.message}finally{button.disabled=false}}}\nfunction render(){if(!state)return;document.body.classList.remove('auth-mode');const page=['registration','security'].includes(location.hash.slice(1))?location.hash.slice(1):'vps';$('#breadcrumb').textContent=({vps:'VPS 管理',registration:'注册设置',security:'账户安全'})[page];document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+page));$('#page').innerHTML=page==='vps'?vpsPage():page==='registration'?registrationPage():securityPage();if(page==='vps'){$('#search').value=query;drawRows()}else if(page==='registration')bindSettings();else bindPassword()}\nfunction vpsPage(){return `<div class=\"title-row\"><div><h1>VPS 管理</h1><p class=\"subtitle\">一个订阅入口，独立连接每一台 VPS。</p></div><button class=\"btn\" onclick=\"refresh().catch(e=>toast(e.message))\">刷新列表</button></div><div class=\"summary\"><section class=\"card stat\"><span class=\"stat-label\">已注册 VPS</span><strong>${state.nodes.length}<em>台</em></strong><small>UUID 与公网 IP 独立绑定</small></section><section class=\"card stat\"><span class=\"stat-label\">订阅代理已启用</span><strong>${state.nodes.filter(n=>n.enabled).length}<em>台</em></strong><small>禁用后立即拒绝新订阅请求</small></section><section class=\"card stat\"><span class=\"stat-label\">新 VPS 注册</span><strong style=\"font-size:24px\">${state.registration?'允许注册':'暂停注册'}</strong><small>${state.tokenConfigured?'已设置注册令牌':'尚未设置令牌，注册将被拒绝'}</small></section></div><section class=\"card\"><div class=\"table-toolbar\"><input class=\"search\" id=\"search\" aria-label=\"搜索 VPS\" placeholder=\"搜索公网 IP、名称或 UUID\" oninput=\"query=this.value;drawRows()\"><div class=\"filters\">${[['all','全部'],['on','已启用'],['off','已禁用']].map(([v,label])=>`<button class=\"${filter===v?'active':''}\" onclick=\"filter='${v}';render()\">${label}</button>`).join('')}</div></div><div class=\"table-wrap\"><table><thead><tr><th>VPS 名称</th><th>公网 IP / UUID</th><th>回源地址</th><th>订阅状态</th><th>最近订阅请求</th><th>操作</th></tr></thead><tbody id=\"rows\"></tbody></table></div><div class=\"table-footer\" id=\"rowCount\"></div></section><div class=\"explain\"><b>禁用只影响 Workers 订阅入口。</b>不会停用实际节点或本机订阅。回源失败不会自动删除 VPS。</div>`}\nfunction drawRows(){const list=state.nodes.filter(n=>(n.name+' '+n.ip+' '+n.id).toLowerCase().includes(query.toLowerCase())&&(filter==='all'||n.enabled===(filter==='on')));$('#rows').innerHTML=list.map(n=>`<tr><td><div class=\"name\"><span class=\"node-icon\">VP</span><div><b>${esc(n.name)}</b><small>注册于 ${esc(date(n.registered))}</small></div></div></td><td><span class=\"ip\">${esc(n.ip)}</span><span class=\"uuid\" title=\"${esc(n.id)}\">${esc(n.id.slice(0,8))}…${esc(n.id.slice(-4))}</span></td><td><div class=\"origin\" title=\"${esc(n.origin)}\">${esc(n.origin)}</div></td><td><span class=\"badge ${n.enabled?'':'off'}\">${n.enabled?'已启用':'已禁用'}</span></td><td>${esc(date(n.last_request))}</td><td><button class=\"op\" onclick=\"details('${n.id}')\">详情</button><button class=\"op\" onclick=\"toggleNode('${n.id}')\">${n.enabled?'禁用':'恢复'}</button><button class=\"op red\" onclick=\"removeNode('${n.id}')\">删除</button></td></tr>`).join('')||'<tr><td colspan=\"6\" class=\"empty\">暂无 VPS，先在注册设置中设置令牌，再从 VPS 网页注册接入。</td></tr>';$('#rowCount').textContent=`显示 ${list.length} 台，共 ${state.nodes.length} 台 VPS`}\nfunction details(id){const n=state.nodes.find(n=>n.id===id);modal(`<h2>${esc(n.name)}</h2><p>公网 IP</p><div class=\"ip\">${esc(n.ip)}</div><p>VPS UUID</p><div class=\"code\">${esc(n.id)}</div><p>回源地址</p><div class=\"code\">${esc(n.origin)}</div><p>注册时间：${esc(date(n.registered))}<br>最近连接：${esc(date(n.last_seen))}<br>最近订阅请求：${esc(date(n.last_request))}</p><p>订阅地址结构</p><div class=\"code\">${esc(location.origin)}/sub/${esc(n.id)}/&lt;用户订阅令牌&gt;?format=uri</div><div class=\"actions\"><button class=\"btn\" id=\"copyUuid\">复制 UUID</button></div>`);$('#copyUuid').onclick=()=>navigator.clipboard.writeText(n.id).then(()=>toast('UUID 已复制')).catch(()=>toast('请手动复制 UUID'))}\nasync function nodeAction(id,action){try{accept(await api('/api/node/action',{id,action}));$('#modal').close();toast('已保存')}catch(e){toast(e.message)}}\nfunction toggleNode(id){const n=state.nodes.find(n=>n.id===id);if(!n.enabled){nodeAction(id,'enable');return}modal(`<h2>禁用这台 VPS 的订阅？</h2><p>${esc(n.name)} · ${esc(n.ip)}</p><p>仅拒绝 Workers 订阅请求，保留绑定；不会停用实际节点。</p><div class=\"actions\"><button class=\"btn\" onclick=\"$('#modal').close()\">取消</button><button class=\"btn primary\" id=\"confirmDisable\">禁用订阅代理</button></div>`);$('#confirmDisable').onclick=()=>nodeAction(id,'disable')}\nfunction removeNode(id){const n=state.nodes.find(n=>n.id===id);modal(`<h2>删除 VPS 绑定？</h2><p>${esc(n.name)} · ${esc(n.ip)}</p><p>原 Workers 订阅地址失效，该 VPS 的管理密钥将被撤销。重新接入需要注册令牌。</p><div class=\"actions\"><button class=\"btn\" onclick=\"$('#modal').close()\">取消</button><button class=\"btn danger\" id=\"confirmDelete\">删除绑定</button></div>`);$('#confirmDelete').onclick=()=>nodeAction(id,'delete')}\nfunction registrationPage(){return `<div class=\"title-row\"><div><h1>注册设置</h1><p class=\"subtitle\">注册令牌仅用于接入，不能登录管理员面板。</p></div></div><div class=\"settings-grid\"><section class=\"card settings-card\"><h2>接入控制</h2><div class=\"setting-row\"><div><h3>允许新 VPS 注册</h3><p class=\"muted\">关闭后不影响已注册 VPS。</p></div><button class=\"switch ${state.registration?'on':''}\" id=\"registrationSwitch\" role=\"switch\" aria-label=\"允许新 VPS 注册\" aria-checked=\"${state.registration}\"></button></div><div class=\"token-state\"><div><b>注册令牌</b><p class=\"muted\">${state.tokenConfigured?'已设置 · 不回显':'尚未配置'}</p></div><code>${state.tokenConfigured?'••••••••':'—'}</code></div><p class=\"muted\">最近更换：${esc(date(state.tokenUpdated))}</p><form id=\"tokenForm\"><label>设置新的注册令牌<input name=\"token\" type=\"password\" minlength=\"24\" maxlength=\"256\" autocomplete=\"off\" placeholder=\"至少 24 位\" required></label><p class=\"muted\">更换后旧令牌失效，已注册 VPS 的独立密钥不受影响。</p><div class=\"actions\"><button type=\"button\" class=\"btn\" id=\"generateToken\">随机生成</button><button class=\"btn primary\" type=\"submit\">保存注册令牌</button></div></form></section><section class=\"card settings-card\"><h2>VPS 接入方式</h2><p class=\"muted\">在 VPS 网页填写服务地址与注册令牌：</p><div class=\"code\">${esc(location.origin)}</div><ul><li>VPS 提交 UUID、公网 IP、HTTPS 回源订阅地址。</li><li>首次注册验证注册令牌，后续用独立密钥更新。</li><li>订阅实时回源，不存储用户或节点快照。</li><li>VPS 离线时刷新订阅会失败，不删除绑定。</li></ul></section></div>`}\nfunction bindSettings(){$('#registrationSwitch').onclick=async()=>{try{accept(await api('/api/settings',{registration:!state.registration}));toast('已更新')}catch(e){toast(e.message)}};$('#generateToken').onclick=()=>{const token=Array.from(crypto.getRandomValues(new Uint8Array(32)),b=>b.toString(16).padStart(2,'0')).join('');$('#tokenForm').elements.token.value=token;modal('<h2>已生成注册令牌</h2><p>请复制保存。关闭弹窗后，点击「保存注册令牌」才会生效。</p><div class=\"code\" id=\"generatedToken\"></div><div class=\"actions\"><button class=\"btn primary\" id=\"copyGenerated\">复制令牌</button></div>');$('#generatedToken').textContent=token;$('#copyGenerated').onclick=()=>navigator.clipboard.writeText(token).then(()=>toast('已复制')).catch(()=>toast('请手动复制'))};$('#tokenForm').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('[type=submit]');button.disabled=true;try{accept(await api('/api/settings',{registration:state.registration,token:new FormData(e.target).get('token')}));toast('注册令牌已更新')}catch(error){toast(error.message)}finally{button.disabled=false}}}\nfunction securityPage(){return `<div class=\"title-row\"><div><h1>账户安全</h1><p class=\"subtitle\">管理员账号 dywsun；修改密码后所有已登录会话失效。</p></div></div><section class=\"card settings-card\" style=\"max-width:640px\"><h2>修改管理员密码</h2><form id=\"passwordForm\"><label>原密码<input name=\"current\" type=\"password\" autocomplete=\"current-password\" maxlength=\"256\" required></label><label>新密码<input name=\"password\" type=\"password\" autocomplete=\"new-password\" minlength=\"12\" maxlength=\"256\" required></label><label>确认新密码<input name=\"confirm\" type=\"password\" autocomplete=\"new-password\" minlength=\"12\" maxlength=\"256\" required></label><p class=\"form-error\" id=\"passwordError\" role=\"alert\"></p><div class=\"actions\"><button class=\"btn primary\" type=\"submit\">修改密码并退出登录</button></div></form></section>`}\nfunction bindPassword(){$('#passwordForm').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('[type=submit]');button.disabled=true;try{await api('/api/password',Object.fromEntries(new FormData(e.target)));showLogin();toast('密码已修改，请重新登录')}catch(error){if($('#passwordError'))$('#passwordError').textContent=error.message}finally{button.disabled=false}}}\n$('#logout').onclick=async()=>{try{await api('/api/logout',{});showLogin()}catch(e){toast(e.message)}};\nwindow.addEventListener('hashchange',render);\n(async()=>{try{const b=await api('/api/bootstrap');if(!b.initialized){showLogin(true);return}await refresh()}catch(e){showLogin();if($('#authError'))$('#authError').textContent=e.message}})();\n"};
import {isIP} from 'node:net';
const encoder=new TextEncoder();
const now=()=>Math.floor(Date.now()/1000);
const random=()=>Array.from(crypto.getRandomValues(new Uint8Array(32)),n=>n.toString(16).padStart(2,'0')).join('');
async function digest(text){return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',encoder.encode(text))),b=>b.toString(16).padStart(2,'0')).join('')}
function equal(a,b){if(typeof a!=='string'||typeof b!=='string')return false;let diff=a.length^b.length;for(let i=0;i<Math.max(a.length,b.length);i++)diff|=(a.charCodeAt(i)||0)^(b.charCodeAt(i)||0);return diff===0}
async function passwordHash(password,salt){const key=await crypto.subtle.importKey('raw',encoder.encode(password),'PBKDF2',false,['deriveBits']);return Array.from(new Uint8Array(await crypto.subtle.deriveBits({name:'PBKDF2',hash:'SHA-256',salt:encoder.encode(salt),iterations:100000},key,256)),b=>b.toString(16).padStart(2,'0')).join('')}
const security={'Cache-Control':'no-store','X-Content-Type-Options':'nosniff','X-Frame-Options':'DENY','Referrer-Policy':'no-referrer','Content-Security-Policy':"default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; frame-ancestors 'none'; form-action 'self'; base-uri 'none'"};
function response(value,status=200,headers={}){return new Response(typeof value==='string'?value:JSON.stringify(value),{status,headers:{...security,'Content-Type':'application/json; charset=utf-8',...headers}})}
function fail(message,status=400,code){throw Object.assign(Error(message),{status,code})}
function validPassword(value){if(typeof value!=='string'||value.length<12||value.length>256)fail('密码长度必须为 12–256 个字符')}
function publicIP(ip){if(isIP(ip)===4){const [a,b]=ip.split('.').map(Number);return !(a===0||a===10||a===127||a>=224||a===169&&b===254||a===172&&b>=16&&b<=31||a===192&&b===168||a===100&&b>=64&&b<=127||a===198&&(b===18||b===19))}if(isIP(ip)===6){const n=ip.toLowerCase();return /^[23][0-9a-f]{0,3}:/.test(n)&&!(/^f[cdfe]/.test(n)||n==='::'||n==='::1'||n.includes('.')||n.startsWith('::ffff:'))}return false}
function originURL(value){let url;try{url=new URL(value)}catch{fail('回源地址无效')}
 if(url.protocol!=='https:'||(url.port&&!['443','8443'].includes(url.port))||url.username||url.password||url.search||url.hash||url.pathname.includes('%')||!/^\/(?:[A-Za-z0-9_-]+\/)*sub\/?$/.test(url.pathname))fail('回源需为 HTTPS 订阅接口，不带查询参数')
 if(isIP(url.hostname.replace(/^\[|\]$/g,''))||!/^([a-z0-9][a-z0-9-]*\.)+[a-z]{2,63}$/.test(url.hostname)||/\.(localhost|local|internal|test|invalid)$/.test(url.hostname))fail('回源需使用公网域名及受信任的 HTTPS 证书')
 return url.href.replace(/\/$/,'')}
async function ensurePublicDNS(origin,fetcher){const host=new URL(origin).hostname;let addresses=[];
 for(const type of ['A','AAAA']){let r;try{r=await fetcher('https://cloudflare-dns.com/dns-query?name='+encodeURIComponent(host)+'&type='+type,{headers:{Accept:'application/dns-json'},signal:AbortSignal.timeout(6000)})}catch{fail('无法验证回源 DNS',502)}if(!r.ok)fail('无法验证回源 DNS',502);const data=await r.json();addresses.push(...(data.Answer||[]).filter(a=>a.type===1||a.type===28).map(a=>a.data))}
 if(!addresses.length||addresses.some(ip=>!publicIP(ip)))fail('回源域名必须仅解析到公网 IP');}
async function bodyJSON(request){if(!request.headers.get('Content-Type')?.startsWith('application/json'))fail('需要 JSON 请求',415);const reader=request.body?.getReader();if(!reader)fail('请求体无效');let size=0,parts=[];for(;;){const {done,value}=await reader.read();if(done)break;size+=value.length;if(size>16384){await reader.cancel();fail('请求过大',413)}parts.push(value)}const bytes=new Uint8Array(size);let offset=0;for(const p of parts){bytes.set(p,offset);offset+=p.length}try{const value=JSON.parse(new TextDecoder().decode(bytes));if(!value||Array.isArray(value)||typeof value!=='object')fail('请求体无效');return value}catch{fail('JSON 无效')}}
async function rate(db,request,group,limit){const ip=request.headers.get('CF-Connecting-IP')||'local';const key=group+':'+await digest(ip),bucket=Math.floor(now()/300);const row=await db.prepare('INSERT INTO attempts(key,bucket,count) VALUES(?,?,1) ON CONFLICT(key,bucket) DO UPDATE SET count=count+1 RETURNING count').bind(key,bucket).first();if(row.count>limit)fail('尝试次数过多，请稍后重试',429)}
async function session(db,request){const cookie=request.headers.get('Cookie')||'',token=/(?:^|;\s*)__Host-relay_admin=([a-f0-9]{64})(?:;|$)/.exec(cookie)?.[1];if(!token)return null;return db.prepare('SELECT s.token_hash,s.csrf,s.version,s.expires FROM sessions s JOIN admin a ON a.id=1 AND a.version=s.version WHERE s.token_hash=? AND s.expires>?').bind(await digest(token),now()).first()}
async function adminState(db,s){const settings=await db.prepare('SELECT * FROM settings WHERE id=1').first();const rows=await db.prepare('SELECT id,ip,name,origin,enabled,registered,last_seen,last_request FROM nodes ORDER BY registered DESC').all();return {csrf:s.csrf,username:'dywsun',registration:!!settings.registration,tokenConfigured:!!settings.token_hash,tokenUpdated:settings.token_updated,nodes:rows.results.map(n=>({...n,enabled:!!n.enabled}))}}
const cookie=(value,maxAge=28800)=>`__Host-relay_admin=${value}; Secure; HttpOnly; SameSite=Strict; Path=/; Max-Age=${maxAge}`;
function makeWorker(fetcher=(...args)=>fetch(...args)){
return {async fetch(request,env,ctx){try{
 const url=new URL(request.url),path=url.pathname,db=env.DB.withSession?env.DB.withSession('first-primary'):env.DB;
 if(url.protocol!=='https:'&&url.hostname!=='localhost'&&url.hostname!=='127.0.0.1')return response({error:'需要 HTTPS'},403);
 // Explicit whitelist: source files, databases and configuration are never web assets.
 if(request.method==='GET'&&['/','/assets/app.js','/assets/style.css'].includes(path)){
   const assets=typeof RELAY_ASSETS==='undefined'?{}:RELAY_ASSETS;
   if(!(path in assets))return response({error:'请先构建 Worker'},503);
   return response(assets[path],200,{'Content-Type':path==='/'?'text/html; charset=utf-8':path.endsWith('.js')?'text/javascript; charset=utf-8':'text/css; charset=utf-8'});
 }
 if(path==='/api/bootstrap'&&request.method==='GET'){const a=await db.prepare('SELECT id FROM admin WHERE id=1').first();return response({initialized:!!a,username:'dywsun'})}
 if(path.startsWith('/sub/')&&['GET','HEAD'].includes(request.method)){
   const m=/^\/sub\/([a-f0-9-]{36})\/([A-Za-z0-9_-]{32,128})$/.exec(path);if(!m)return response('Not found',404,{'Content-Type':'text/plain'});
   const node=await db.prepare('SELECT * FROM nodes WHERE id=? AND enabled=1').bind(m[1]).first();if(!node)return response('Not found',404,{'Content-Type':'text/plain'});
   const fmt=url.searchParams.get('format')||'uri';if(!['uri','karing','mihomo','singbox'].includes(fmt))fail('格式无效');
   const origin=originURL(node.origin);if(new URL(origin).hostname===url.hostname)fail('回源不能指向自身');await ensurePublicDNS(origin,fetcher);
   let upstream;try{upstream=await fetcher(origin+'/'+m[2]+'?format='+fmt,{method:request.method,redirect:'manual',cache:'no-store',signal:AbortSignal.timeout(10000),headers:{'Accept-Encoding':'identity'}})}catch{return response('Subscription origin unavailable',502,{'Content-Type':'text/plain'})}
   if(upstream.status>=300&&upstream.status<400){await upstream.body?.cancel();return response('Origin redirects are not allowed',502,{'Content-Type':'text/plain'})}
   // Recheck after network I/O so a concurrent disable/delete cannot release a new subscription.
   const active=await db.prepare('SELECT id FROM nodes WHERE id=? AND enabled=1 AND origin=?').bind(node.id,node.origin).first();if(!active){await upstream.body?.cancel();return response('Not found',404,{'Content-Type':'text/plain'})}
   const update=db.prepare('UPDATE nodes SET last_request=? WHERE id=?').bind(now(),node.id).run();if(ctx)ctx.waitUntil(update);else await update;
   const type=upstream.headers.get('Content-Type')||'text/plain; charset=utf-8';
   const headers={...security,'Content-Security-Policy':"default-src 'none'; sandbox",'Content-Type':/^(text\/(plain|yaml)|application\/(json|yaml|octet-stream))(;|$)/i.test(type)?type:'text/plain; charset=utf-8'};
   for(const name of ['Subscription-Userinfo','profile-update-interval'])if(upstream.headers.has(name))headers[name]=upstream.headers.get(name);
   return new Response(upstream.body,{status:upstream.status,headers});
 }
 if(path==='/api/register'&&request.method==='POST'){
   await rate(db,request,'register',20);const p=await bodyJSON(request),settings=await db.prepare('SELECT * FROM settings WHERE id=1').first();
   const token=request.headers.get('Authorization')?.replace(/^Bearer /,'')||'';
   if(!settings.registration)fail('Registration is paused',403,'REGISTRATION_PAUSED');
   if(!settings.token_hash)fail('Registration token has not been saved',403,'TOKEN_NOT_CONFIGURED');
   if(!equal(await digest(token),settings.token_hash))fail('Registration token does not match',403,'TOKEN_MISMATCH');
   if(!/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/.test(p.id)||!publicIP(p.ip)||typeof p.name!=='string'||!p.name.trim()||p.name.length>64||! /^[a-f0-9]{64}$/.test(p.key))fail('UUID、公网 IP、名称或管理密钥无效');
   const origin=originURL(p.origin);if(new URL(origin).hostname===url.hostname)fail('回源不能指向 Worker 自身');await ensurePublicDNS(origin,fetcher);
   const hash=await digest(p.key),old=await db.prepare('SELECT * FROM nodes WHERE id=?').bind(p.id).first();
   if(old){if(!equal(old.key_hash,hash)||old.ip!==p.ip||old.origin!==origin)fail('UUID 已绑定其他机器，请用独立管理密钥更新',409);return response({ok:true,id:p.id})}
   const result=await db.prepare('INSERT OR IGNORE INTO nodes(id,ip,name,origin,key_hash,registered,last_seen) VALUES(?,?,?,?,?,?,?)').bind(p.id,p.ip,p.name.trim(),origin,hash,now(),now()).run();if(!result.meta.changes)fail('UUID 已注册，请重试',409);
   return response({ok:true,id:p.id});
 }
 if(path==='/api/node/update'&&request.method==='POST'){
   const p=await bodyJSON(request),node=await db.prepare('SELECT * FROM nodes WHERE id=?').bind(p.id||'').first();const token=request.headers.get('Authorization')?.replace(/^Bearer /,'')||'';
   if(!node||!equal(node.key_hash,await digest(token)))fail('VPS 管理密钥无效',403);
   if(p.ip&&!publicIP(p.ip))fail('公网 IP 无效');const origin=p.origin?originURL(p.origin):node.origin;
   if(new URL(origin).hostname===url.hostname)fail('回源不能指向自身');if(p.origin)await ensurePublicDNS(origin,fetcher);
   const update=await db.prepare('UPDATE nodes SET ip=?,origin=?,last_seen=? WHERE id=? AND key_hash=?').bind(p.ip||node.ip,origin,now(),node.id,node.key_hash).run();if(!update.meta.changes)fail('绑定已撤销',403);return response({ok:true,enabled:!!node.enabled});
 }
 if(path==='/api/state'&&request.method==='GET'){const s=await session(db,request);if(!s)fail('请先登录',401);return response(await adminState(db,s))}
 if(request.method!=='POST')return response({error:'Not found'},404);
 if(request.headers.get('Origin')!==url.origin)fail('请求来源无效',403);
 const p=await bodyJSON(request);
 if(path==='/api/setup'){
   await rate(db,request,'setup',10);if(await db.prepare('SELECT id FROM admin WHERE id=1').first())fail('管理员已初始化',409);
   validPassword(p.password);if(p.password!==p.confirm)fail('两次密码不一致');const salt=random(),hash=await passwordHash(p.password,salt);
   const result=await db.prepare('INSERT OR IGNORE INTO admin(id,salt,hash) VALUES(1,?,?)').bind(salt,hash).run();if(!result.meta.changes)fail('管理员已初始化',409);return response({ok:true});
 }
 if(path==='/api/login'){
   await rate(db,request,'login',15);const a=await db.prepare('SELECT * FROM admin WHERE id=1').first();if(!a)fail('请先设置密码',409);
   const hash=await passwordHash(typeof p.password==='string'?p.password.slice(0,257):'',a.salt);if(p.username!=='dywsun'||!equal(a.hash,hash))fail('账号或密码错误',401);
   const token=random(),csrf=random();await db.prepare('INSERT INTO sessions(token_hash,csrf,version,expires) SELECT ?,?,version,? FROM admin WHERE id=1 AND version=?').bind(await digest(token),csrf,now()+28800,a.version).run();
   return response({csrf},200,{'Set-Cookie':cookie(token)});
 }
 const s=await session(db,request);if(!s)fail('请先登录',401);if(!equal(request.headers.get('X-CSRF-Token'),s.csrf))fail('CSRF 校验失败',403);
 if(path==='/api/logout'){await db.prepare('DELETE FROM sessions WHERE token_hash=?').bind(s.token_hash).run();return response({ok:true},200,{'Set-Cookie':cookie('',0)})}
 if(path==='/api/password'){
   await rate(db,request,'password',10);const a=await db.prepare('SELECT * FROM admin WHERE id=1').first();if(typeof p.current!=='string'||p.current.length>256||!equal(await passwordHash(p.current,a.salt),a.hash))fail('原密码错误',403);
   validPassword(p.password);if(p.password!==p.confirm)fail('两次新密码不一致');const salt=random(),hash=await passwordHash(p.password,salt);
   const result=await db.prepare('UPDATE admin SET salt=?,hash=?,version=version+1 WHERE id=1 AND version=?').bind(salt,hash,a.version).run();if(!result.meta.changes)fail('密码已更新，请重新登录',409);
   await db.prepare('DELETE FROM sessions WHERE version<=?').bind(a.version).run();return response({ok:true},200,{'Set-Cookie':cookie('',0)});
 }
 if(path==='/api/settings'){
   if(typeof p.registration!=='boolean')fail('注册设置无效');let hash=null;
   if(typeof p.token==='string')p.token=p.token.trim();
   if(p.token!==undefined){if(typeof p.token!=='string'||p.token.length<24||p.token.length>256)fail('注册令牌长度必须为 24–256 位');hash=await digest(p.token)}
   if(hash)await db.prepare('UPDATE settings SET registration=?,token_hash=?,token_updated=? WHERE id=1').bind(+p.registration,hash,now()).run();else await db.prepare('UPDATE settings SET registration=? WHERE id=1').bind(+p.registration).run();
   return response(await adminState(db,s));
 }
 if(path==='/api/node/action'){
   if(!['enable','disable','delete'].includes(p.action))fail('操作无效');
   if(p.action==='delete')await db.prepare('DELETE FROM nodes WHERE id=?').bind(p.id).run();else await db.prepare('UPDATE nodes SET enabled=? WHERE id=?').bind(p.action==='enable'?1:0,p.id).run();
   return response(await adminState(db,s));
 }
 return response({error:'Not found'},404);
}catch(e){return response({code:e.code,error:e.status?e.message:'服务暂不可用，请检查数据库绑定与表结构'},e.status||503)}}};}
export default makeWorker();
